bool Groups::validateJsonForCreation(const Json::Value &pJson, std::string &err)
{
    if(pJson.isMember("id"))
    {
        if(!validJsonOfField(0, "id", pJson["id"], err, true))
            return false;
    }
    if(pJson.isMember("external_id"))
    {
        if(!validJsonOfField(1, "external_id", pJson["external_id"], err, true))
            return false;
    }
    if(pJson.isMember("status_enum"))
    {
        if(!validJsonOfField(2, "status_enum", pJson["status_enum"], err, true))
            return false;
    }
    if(pJson.isMember("activation_date"))
    {
        if(!validJsonOfField(3, "activation_date", pJson["activation_date"], err, true))
            return false;
    }
    if(pJson.isMember("office_id"))
    {
        if(!validJsonOfField(4, "office_id", pJson["office_id"], err, true))
            return false;
    }
    if(pJson.isMember("staff_id"))
    {
        if(!validJsonOfField(5, "staff_id", pJson["staff_id"], err, true))
            return false;
    }
    if(pJson.isMember("parent_id"))
    {
        if(!validJsonOfField(6, "parent_id", pJson["parent_id"], err, true))
            return false;
    }
    if(pJson.isMember("level_id"))
    {
        if(!validJsonOfField(7, "level_id", pJson["level_id"], err, true))
            return false;
    }
    if(pJson.isMember("display_name"))
    {
        if(!validJsonOfField(8, "display_name", pJson["display_name"], err, true))
            return false;
    }
    else
    {
        err="The display_name column cannot be null";
        return false;
    }
    if(pJson.isMember("hierarchy"))
    {
        if(!validJsonOfField(9, "hierarchy", pJson["hierarchy"], err, true))
            return false;
    }
    if(pJson.isMember("closure_reason_cv_id"))
    {
        if(!validJsonOfField(10, "closure_reason_cv_id", pJson["closure_reason_cv_id"], err, true))
            return false;
    }
    if(pJson.isMember("closedon_date"))
    {
        if(!validJsonOfField(11, "closedon_date", pJson["closedon_date"], err, true))
            return false;
    }
    if(pJson.isMember("activatedon_userid"))
    {
        if(!validJsonOfField(12, "activatedon_userid", pJson["activatedon_userid"], err, true))
            return false;
    }
    if(pJson.isMember("submittedon_date"))
    {
        if(!validJsonOfField(13, "submittedon_date", pJson["submittedon_date"], err, true))
            return false;
    }
    if(pJson.isMember("submittedon_userid"))
    {
        if(!validJsonOfField(14, "submittedon_userid", pJson["submittedon_userid"], err, true))
            return false;
    }
    if(pJson.isMember("closedon_userid"))
    {
        if(!validJsonOfField(15, "closedon_userid", pJson["closedon_userid"], err, true))
            return false;
    }
    if(pJson.isMember("account_no"))
    {
        if(!validJsonOfField(16, "account_no", pJson["account_no"], err, true))
            return false;
    }
    else
    {
        err="The account_no column cannot be null";
        return false;
    }
    return true;
}
